/* Airbnb DNA — warm white, coral accent, very rounded, soft diffuse shadows */
.theme-airbnb-dna {
  --bg: oklch(0.995 0.003 60);
  --surface: oklch(1 0 0);
  --surface-2: oklch(0.972 0.006 60);
  --fg: oklch(0.252 0 0);
  --fg-muted: oklch(0.55 0.012 40);
  --accent: oklch(0.658 0.231 17.1);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.55 0.13 340);
  --line: oklch(0.9 0.006 60);
  --success: oklch(0.62 0.14 160);
  --warning: oklch(0.8 0.15 80);
  --danger: oklch(0.58 0.22 25);

  --radius: 0.875rem;
  --radius-sm: 0.625rem;
  --radius-lg: 1.25rem;
  --radius-pill: 9999px;

  --shadow-1: 0 2px 6px oklch(0.3 0.02 40 / 8%);
  --shadow-2: 0 6px 20px oklch(0.3 0.02 40 / 12%);
  --shadow-3: 0 16px 40px oklch(0.3 0.02 40 / 18%);
  --glow: 0 0 0 2px color-mix(in oklab, var(--fg) 85%, transparent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Plus Jakarta Sans", sans-serif;
  --font-body: "Plus Jakarta Sans", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.02em;
  --label-transform: none;
  --label-tracking: 0em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-airbnb-dna h1,
.theme-airbnb-dna h2,
.theme-airbnb-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 700;
}

.theme-airbnb-dna button {
  transition: transform 140ms ease, box-shadow 140ms ease;
}

.theme-airbnb-dna button:hover {
  transform: scale(1.02);
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
